def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "navigate_to_bathroom": And([
            self.floor_is_wet,
            self.human_is_nearby,
            Not(self.floor_is_dry)
        ]),
        "initiate_cleaning": And([
            self.floor_is_wet,
            self.human_is_nearby,
            Not(self.floor_is_dry)
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
